questionvariables.text:
kgrp(n) := block([s, out, k], s: string(n), k: slength(s), if k < 5 then s else (out: "", while k > 3 do (out: sconcat("\\,", substring(s, k-2, k+1), out), k: k-3), sconcat(substring(s, 1, k+1), out)));
ksh(v) := block([c, w, f], c: floor(100*v+1/2), w: floor(c/100), f: c-100*w, if f = 0 then kgrp(w) else sconcat(kgrp(w), ".", if f < 10 then "0" else "", string(f)));
dd(v) := if integerp(v) then v else if integerp(10*v) then dispdp(float(v),1) else if integerp(100*v) then dispdp(float(v),2) else if integerp(1000*v) then dispdp(float(v),3) else dispdp(float(v),4);
fr(v) := if integerp(v) then string(v) else sconcat("\\frac{", string(num(v)), "}{", string(denom(v)), "}");
r1(v) := floor(10*v+1/2)/10;
ix: 1+rand(10);
/* Design: mixing ratio for a target price. Source: original. [p1, p2, p, grades]: cheaper grade at p1, dearer at p2, target p. Equalities on integers are exact. Curated list, one seed per entry. */
L: [[1250,1800,1580,["grade AB coffee","grade AA coffee","AB","AA"]],[145,235,175,["ordinary rice","pishori rice","ordinary","pishori"]],[120,175,142,["mwitemania beans","rosecoco beans","mwitemania","rosecoco"]],[1300,1900,1620,["grade AB coffee","grade AA coffee","AB","AA"]],[150,250,175,["ordinary rice","pishori rice","ordinary","pishori"]],[115,160,133,["mwitemania beans","rosecoco beans","mwitemania","rosecoco"]],[1200,1650,1350,["grade AB coffee","grade AA coffee","AB","AA"]],[125,205,175,["ordinary rice","pishori rice","ordinary","pishori"]],[110,170,150,["mwitemania beans","rosecoco beans","mwitemania","rosecoco"]],[1350,1850,1500,["grade AB coffee","grade AA coffee","AB","AA"]]];
E: L[ix];
p1: E[1]; p2: E[2]; p: E[3]; G: E[4];
dc: p-p1; dd2: p2-p;
gg: gcd(dd2, dc);
r1c: dd2/gg; r2c: dc/gg;
gp: gcd(p1, p2);
pr1: p1/gp; pr2: p2/gp;
nr: if dc<dd2 then "cheaper" else "dearer";

feedbackvariables.text:
isint: is(integerp(ans1) and integerp(ans2));
okv: is(isint and ans1>0 and ans2>0 and ans1*dc=ans2*dd2);
okc: is(okv and gcd(ans1,ans2)=1);
rev: is(ans1>0 and ans2>0 and ans1*dd2=ans2*dc);
prc: is(ans1>0 and ans2>0 and ans1*p2=ans2*p1);
mc: if is(ans1>=0 and ans2>=0 and ans1+ans2>0) then (ans1*p1+ans2*p2)/(ans1+ans2) else 0;
sd(v) := dd(floor(100*v+1/2)/100);
sd3(v) := dd(floor(1000*v+1/2)/1000);
ab(v, k) := if is(abs(v-floor(10^k*v+1/2)/10^k) < 10^(-9)) then "" else "about ";
